SELECT is_active, credit_limit_bucket, country_values, us_count FROM (SELECT is_active, CASE WHEN credit_limit >= 15800 THEN 'high' WHEN credit_limit >= 7200 THEN 'mid' ELSE 'low' END AS credit_limit_bucket, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(country))) AS country_values, SUM(CASE WHEN country = 'US' THEN 1 ELSE 0 END) AS us_count FROM customers GROUP BY is_active, CASE WHEN credit_limit >= 15800 THEN 'high' WHEN credit_limit >= 7200 THEN 'mid' ELSE 'low' END) AS t WHERE us_count < 50 ORDER BY us_count DESC
